INSERT INTO public.parking_spots (
    name,
    city,
    address,
    location,
    total_car_slots,
    total_bike_slots,
    is_paid,
    price_per_hour,
    rule_type,
    rule_description,
    external_spot_id
)
SELECT
    i.name,
    i.city,
    i.address,
    ST_SetSRID(ST_MakePoint(i.longitude, i.latitude), 4326)::geography,
    i.total_car_slots,
    i.total_bike_slots,
    i.is_paid,
    i.price_per_hour,
    i.rule_type,
    i.rule_description,
    i.external_spot_id
FROM incoming i
ON CONFLICT (external_spot_id) DO NOTHING
RETURNING id, city, name, external_spot_id;
